<!doctype html><html><head><meta charset="utf-8"><title>{{ $tax->title }} Letter</title><style>body{font-family:Georgia,serif;color:#111;margin:48px}.letter{border:2px solid #111;padding:36px}.center{text-align:center}.muted{color:#555}.row{display:flex;justify-content:space-between}.seal{border:2px solid #333;border-radius:50%;width:110px;height:110px;display:flex;align-items:center;justify-content:center;text-align:center;font-weight:bold}@media print{button{display:none}}</style></head><body><button onclick="window.print()">Print / Save PDF</button><div class="letter"><div class="center"><h1>Punjab Lottery</h1><h2>{{ strtoupper($tax->title) }} PAYMENT NOTICE</h2><p class="muted">Reference: TAX-{{ str_pad($tax->id,6,'0',STR_PAD_LEFT) }}</p></div><hr><p>Date: {{ now()->format('d M Y') }}</p><p>This letter confirms that <strong>{{ $tax->customer->name }}</strong> has been issued a {{ $tax->tax_type }} charge against withdrawal request #{{ $tax->withdrawal_request_id }} for winning ticket <strong>{{ $tax->withdrawal->item->ticket_uid }}</strong>.</p><p>Tax title: <strong>{{ $tax->title }}</strong><br>Amount payable: <strong>Rs {{ number_format($tax->amount,2) }}</strong><br>Status: <strong>{{ ucfirst($tax->status) }}</strong></p><p>{{ $tax->description }}</p><div class="row"><div><p>Customer UTR: {{ $tax->payment_utr ?? 'Pending' }}</p><p>Issued by Punjab Lottery Administration</p></div><div class="seal">Punjab<br>Lottery<br>Tax</div></div></div></body></html>
